describe('Page Navigation - Jump to Specific Page', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="pagination-container"]').should('be.visible');
  });

  it('should jump to a specific page when entering a valid page number', () => {
    cy.get('[data-testid="page-input"]').should('be.visible');
    cy.get('[data-testid="page-input"]').clear().type('5');
    cy.get('[data-testid="go-to-page-button"]').click();

    cy.get('[data-testid="current-page"]').should('contain', '5');
    cy.get('[data-testid="page-content"]').should('contain', 'Page 5');
    cy.url().should('include', 'page=5');
  });

  it('should display error message when entering an invalid page number', () => {
    cy.get('[data-testid="page-input"]').clear().type('999');
    cy.get('[data-testid="go-to-page-button"]').click();

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Page number out of range');
    cy.get('[data-testid="current-page"]').should('not.contain', '999');
  });

  it('should not navigate when page input is empty', () => {
    const initialPage = '1';
    cy.get('[data-testid="current-page"]').then(($el) => {
      cy.wrap($el.text()).as('initialPageNumber');
    });

    cy.get('[data-testid="page-input"]').clear();
    cy.get('[data-testid="go-to-page-button"]').click();

    cy.get('@initialPageNumber').then((initialPageNumber) => {
      cy.get('[data-testid="current-page"]').should('contain', initialPageNumber);
    });
  });

  it('should handle negative page numbers gracefully', () => {
    cy.get('[data-testid="page-input"]').clear().type('-1');
    cy.get('[data-testid="go-to-page-button"]').click();

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Page number must be positive');
  });

  it('should jump to page 1 when entering minimum valid page number', () => {
    cy.get('[data-testid="page-input"]').clear().type('1');
    cy.get('[data-testid="go-to-page-button"]').click();

    cy.get('[data-testid="current-page"]').should('contain', '1');
    cy.get('[data-testid="page-content"]').should('contain', 'Page 1');
  });
});
